From 315fc3aee413979a92066d14f13ac4fe402d3f68 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 01:55:34 +0100
Subject: [PATCH] kcm: add an option to not switch to newly connected devices

WirePlumber makes a newly connected device with a higher priority the
default. The new option toggles WirePlumber's setting to keep the current
one instead, and is only shown when the running WirePlumber has it.

BUG: 516683
---
 src/CMakeLists.txt         |  1 +
 src/kcm/ui/main.qml        | 20 ++++++--
 src/wireplumbersetting.cpp | 97 ++++++++++++++++++++++++++++++++++++++
 src/wireplumbersetting.h   | 37 +++++++++++++++
 4 files changed, 152 insertions(+), 3 deletions(-)
 create mode 100644 src/wireplumbersetting.cpp
 create mode 100644 src/wireplumbersetting.h

diff --git a/src/CMakeLists.txt b/src/CMakeLists.txt
index 487398a8..638f4359 100644
--- a/src/CMakeLists.txt
+++ b/src/CMakeLists.txt
@@ -20,6 +20,7 @@ set(plasma-volume_SRCS
     devicerenamesaver.cpp devicerenamesaver.h
     percentvalidator.cpp percentvalidator.h
     microphonetest.cpp microphonetest.h
+    wireplumbersetting.cpp wireplumbersetting.h
 )

 ecm_qt_declare_logging_category(plasma-volume_SRCS HEADER debug.h IDENTIFIER PLASMAPA
diff --git a/src/kcm/ui/main.qml b/src/kcm/ui/main.qml
index 140954d7..f3be9d60 100644
--- a/src/kcm/ui/main.qml
+++ b/src/kcm/ui/main.qml
@@ -60,6 +60,11 @@ KCM.ScrollViewKCM {
         sourceModel: paSourceModel
     }

+    WirePlumberSetting {
+        id: switchToNewDevices
+        key: "stream.switch-to-new-default-targets"
+    }
+
     ModuleManager {
         id: moduleManager
     }
@@ -89,25 +94,34 @@ KCM.ScrollViewKCM {
         },
         Kirigami.Action {
             id: configureButton
-            visible: moduleManager.settingsSupported
-            enabled: moduleManager.configModuleLoaded
+            visible: moduleManager.settingsSupported || switchToNewDevices.available
+            enabled: !moduleManager.settingsSupported || moduleManager.configModuleLoaded
             text: i18nd("kcm_pulseaudio", "Configure…")
             icon.name: "configure"

-            tooltip: i18nd("kcm_pulseaudio", "Requires %1 PulseAudio module", moduleManager.configModuleName)
+            tooltip: moduleManager.settingsSupported ? i18nd("kcm_pulseaudio", "Requires %1 PulseAudio module", moduleManager.configModuleName) : ""

             Kirigami.Action {
+                visible: moduleManager.settingsSupported
                 text: i18nd("kcm_pulseaudio", "Add virtual output device for simultaneous output on all local sound cards")
                 checkable: true
                 checked: moduleManager.combineSinks
                 onToggled: moduleManager.combineSinks = checked
             }
             Kirigami.Action {
+                visible: moduleManager.settingsSupported
                 text: i18nd("kcm_pulseaudio", "Automatically switch all running streams when a new output becomes available")
                 checkable: true
                 checked: moduleManager.switchOnConnect
                 onToggled: moduleManager.switchOnConnect = checked
             }
+            Kirigami.Action {
+                visible: switchToNewDevices.available
+                text: i18nd("kcm_pulseaudio", "Automatically switch to newly connected devices")
+                checkable: true
+                checked: switchToNewDevices.value
+                onToggled: switchToNewDevices.value = checked
+            }
         }
     ]

diff --git a/src/wireplumbersetting.cpp b/src/wireplumbersetting.cpp
new file mode 100644
index 00000000..406d49ee
--- /dev/null
+++ b/src/wireplumbersetting.cpp
@@ -0,0 +1,97 @@
+// SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+// SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+#include "wireplumbersetting.h"
+
+#include <QProcess>
+
+#include "debug.h"
+
+using namespace Qt::StringLiterals;
+
+WirePlumberSetting::WirePlumberSetting(QObject *parent)
+    : QObject(parent)
+{
+}
+
+QString WirePlumberSetting::key() const
+{
+    return m_key;
+}
+
+void WirePlumberSetting::setKey(const QString &key)
+{
+    if (m_key == key) {
+        return;
+    }
+    m_key = key;
+    Q_EMIT keyChanged();
+    load();
+}
+
+bool WirePlumberSetting::isAvailable() const
+{
+    return m_available;
+}
+
+bool WirePlumberSetting::value() const
+{
+    return m_value;
+}
+
+void WirePlumberSetting::setValue(bool value)
+{
+    if (!m_available || m_value == value) {
+        return;
+    }
+    m_value = value;
+    Q_EMIT valueChanged();
+
+    auto wpctl = new QProcess(this);
+    connect(wpctl, &QProcess::finished, this, [this, wpctl](int exitCode, QProcess::ExitStatus exitStatus) {
+        wpctl->deleteLater();
+        if (exitStatus != QProcess::NormalExit || exitCode != 0) {
+            qCWarning(PLASMAPA) << "Failed to save WirePlumber setting" << m_key << wpctl->readAllStandardError();
+            load();
+        }
+    });
+    connect(wpctl, &QProcess::errorOccurred, this, [this, wpctl](QProcess::ProcessError error) {
+        if (error == QProcess::FailedToStart) {
+            qCWarning(PLASMAPA) << "Failed to save WirePlumber setting" << m_key << wpctl->errorString();
+            wpctl->deleteLater();
+            load();
+        }
+    });
+    wpctl->start(u"wpctl"_s, {u"settings"_s, u"--save"_s, m_key, value ? u"true"_s : u"false"_s});
+}
+
+void WirePlumberSetting::load()
+{
+    auto wpctl = new QProcess(this);
+    connect(wpctl, &QProcess::finished, this, [this, wpctl, key = m_key] {
+        wpctl->deleteLater();
+        if (key != m_key) {
+            return;
+        }
+        // Prints "Value: <json>" with " (Saved: <json>)" if saved, or a "not found" message for settings this WirePlumber doesn't have
+        const QString output = QString::fromUtf8(wpctl->readAllStandardOutput()).trimmed();
+        const bool available = output.startsWith("Value: "_L1);
+        const bool value = output.section(u' ', 1, 1) == "true"_L1;
+        if (m_value != value) {
+            m_value = value;
+            Q_EMIT valueChanged();
+        }
+        if (m_available != available) {
+            m_available = available;
+            Q_EMIT availableChanged();
+        }
+    });
+    connect(wpctl, &QProcess::errorOccurred, wpctl, [wpctl](QProcess::ProcessError error) {
+        if (error == QProcess::FailedToStart) {
+            wpctl->deleteLater();
+        }
+    });
+    wpctl->start(u"wpctl"_s, {u"settings"_s, m_key});
+}
+
+#include "moc_wireplumbersetting.cpp"
diff --git a/src/wireplumbersetting.h b/src/wireplumbersetting.h
new file mode 100644
index 00000000..adbcba7a
--- /dev/null
+++ b/src/wireplumbersetting.h
@@ -0,0 +1,37 @@
+// SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+// SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+#pragma once
+
+#include <QObject>
+#include <qqmlregistration.h>
+
+// A boolean WirePlumber setting, read and saved with wpctl
+class WirePlumberSetting : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+    Q_PROPERTY(QString key READ key WRITE setKey NOTIFY keyChanged REQUIRED)
+    Q_PROPERTY(bool available READ isAvailable NOTIFY availableChanged)
+    Q_PROPERTY(bool value READ value WRITE setValue NOTIFY valueChanged)
+public:
+    explicit WirePlumberSetting(QObject *parent = nullptr);
+
+    [[nodiscard]] QString key() const;
+    void setKey(const QString &key);
+    [[nodiscard]] bool isAvailable() const;
+    [[nodiscard]] bool value() const;
+    void setValue(bool value);
+
+Q_SIGNALS:
+    void keyChanged();
+    void availableChanged();
+    void valueChanged();
+
+private:
+    void load();
+
+    QString m_key;
+    bool m_available = false;
+    bool m_value = false;
+};
-- 
